def close_extra_active_conversations(apps, schema_editor):
    """До этапа 3 статуса не было: у владельца остаётся текущим только последний диалог."""
    Conversation = apps.get_model("chat", "Conversation")
    seen = set()
    extra = []
    for conv in Conversation.objects.filter(status="active").order_by("-last_message_at", "-id"):
        owner = ("u", conv.user_id) if conv.user_id else ("s", conv.session_id)
        if owner in seen:
            extra.append(conv.pk)
        else:
            seen.add(owner)
    Conversation.objects.filter(pk__in=extra).update(status="closed")


